output-exprs.el:
ccRecipient:a!localVariables(
  local!group: reject(
    fn!isnull,
    #"SYSTEM_SYSRULES_forEach"(
      items: pv!emailCC,
      expression: if(typeof(fv!item) = 5, fv!item, null)
    )
  ),
  local!user: reject(
    fn!isnull,
    #"SYSTEM_SYSRULES_forEach"(
      items:pv!emailCC,
      expression: if(typeof(fv!item) = 4, fv!item, null)
    )
  ),
  local!users: #"SYSTEM_SYSRULES_forEach"(
    items: local!group,
    expression: property(
      a!groupMembers(group: fv!item),
      "data",
      null
    )
  ),
  local!finalUsers: append(local!user, local!users),
  union(local!finalUsers,local!finalUsers)
)
